UPDATE public.app_state
SET value = $itss_recovery${"units":{"8252":{"activities":{"Formative Assessment":true,"Lesson & Training Aids":true,"Summative Assessment":true,"POE Evidence":true},"quiz":{"best":10,"total":10,"attempts":2,"history":[{"score":10,"total":10,"date":"2026-10-20T18:48:27.137Z"},{"score":7,"total":10,"date":"2026-10-20T18:45:46.423Z"}]},"logbook":{"exq.qs1.0":"1.\tIncident Reports\n2.\tInvestigation Reports\n3.\tProject Status Reports\n","exq.qs1.0.ok":false,"exq.qs1.1":"Incident Report\nContains details of:\nâ¢\tWhat happened\nâ¢\tWho was affected\nâ¢\tImmediate actions taken\nâ¢\tFollow-up actions required\nInvestigation Report\nContains:\nâ¢\tEvidence gathered\nâ¢\tFindings\nâ¢\tRoot cause analysis\nâ¢\tConclusions based on facts\nProject Status Report\nContains:\nâ¢\tProject progress\nâ¢\tRisks and issues\nâ¢\tBudget status\nâ¢\tMilestones achieved\nâ¢\tNext step\n","exq.qs1.1.ok":true,"exq.qs1.2":"â¢\tObtain information only from authorised sources \nâ¢\tTreat all organisational information as confidential.\nâ¢\tVerify that the information is required for a legitimate business purpose.\nâ¢\tShare information only with authorised individuals.\nâ¢\tCheck permission and security clearance levels before distributing information.\nâ¢\tFollow company policies and procedures for handling sensitive information.\nâ¢\tDistribute only the information necessary for the recipient's role.\n","exq.qs1.2.ok":false,"exq.qs1.3":"â¢\tRequest information through approved organisational channels.\nâ¢\tObtain management approval where required.\nâ¢\tAccess information only if authorised.\nâ¢\tFollow confidentiality and security requirements.\nâ¢\tUse approved systems and repositories when collecting information.\nâ¢\tEnsure information is relevant to the task or report being prepared.\nâ¢\tProtect sensitive data from unauthorised access.\n","exq.qs1.3.ok":true,"exq.qs1.4":"Step 1: Determine the Purpose\nUnderstand the objective, audience, and required outcome of the report.\nStep 2: Gather Information\nCollect relevant, accurate, and verifiable information from authorised sources.\nStep 3: Analyse Information\nReview data and identify key findings and facts.\nStep 4: Write the Report\nUse professional language, maintain objectivity, and avoid personal opinions.\nStep 5: Structure the Report\nInclude:\nâ¢\tTitle Page\nâ¢\tAbstract\nâ¢\tTable of Contents\nâ¢\tIntroduction\nâ¢\tMain Body\nâ¢\tConclusion\nâ¢\tRecommendations\nâ¢\tReferences\nâ¢\tAppendices\nStep 6: Review and Edit\nCheck for accuracy, clarity, conciseness, and completeness.\nStep 7: Obtain Approval\nHave a colleague or manager review the report before distribution.\nStep 8: Distribute the Report\nSend it only to the intended audience using approved methods.\n\n","exq.qs1.4.ok":true,"exq.qs1.5":"To ensure compliance with report requirements:\nâ¢\tVerify that all information is accurate and supported by evidence.\nâ¢\tEnsure the report meets the needs of the target audience.\nâ¢\tConfirm that the report achieves its intended purpose.\nâ¢\tReview the report against the project requirements and checklist.\nâ¢\tAsk a colleague to conduct a peer review.\nâ¢\tCorrect any errors, omissions, or biased statements.\nâ¢\tObtain management approval before distribution.\nâ¢\tFollow organisational procedures for collecting and sharing information.\nâ¢\tEnsure confidential information is handled appropriately and only shared with authorised recipients\n","exq.qs1.5.ok":true,"project.upload":"{\"name\":\"Overall_Monthly_Progress_Report_Bonolo_Mekgoe.pdf\",\"type\":\"application/pdf\",\"size\":9857,\"uploadedAt\":\"2026-08-27T19:40:12.254Z\",\"path\":\"019c8179-b1eb-4883-8471-be7ae31f90de/logbook/mtbxg9r2-Overall_Monthly_Progress_Report_Bonolo_Mekgoe.pdf\"}","detail:Learner Name":"Bonolo Mekgoe","detail:Qualification":"Information Technology-System Support","detail:Workplace Name":"Investec","detail:Start Date":"2026-07-01","detail:Completion Date":"2027-06-30","selfassess-1":true,"selfassess-0":true,"selfassess-2":true,"selfassess-3":true,"selfassess-4":true,"selfassess.savedAt":"2026-08-19T11:06:06.961Z","slidegate.7":true,"slidegate.0":true,"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"exq.qs1.0.reviewedText":"","exq.qs1.0.marks":"","quiz.quiz.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[2,3,1,0]},\"1\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[0,2,1,3]},\"2\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[1,2,0,3]},\"3\":{\"kind\":\"choice\",\"picks\":[3],\"disp\":[3,1,0,2]},\"4\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[1,3,0,2]},\"5\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[2,3,0,1]},\"6\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[3,0,2,1]},\"7\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[3,1,2,0]},\"8\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[1,3,2,0]},\"9\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[0,1,2,3]}}"},"exercises":{"qs1":{"best":44,"last":44,"total":62,"attempts":2}},"quizzes":{}},"10135":{"activities":{"Formative Assessment":true,"Lesson & Training Aids":true,"Summative Assessment":true,"POE Evidence":true},"logbook":{"exq.ex1.0":"Communicate-To effectively work as a member of a team, there must be good communication between team members and a willingness to share ideas and information.\nTeam members should listen actively by paying attention to others, asking questions, and acknowledging what has been said.\nIt is important not to blame others for mistakes or missed deadlines, but rather work together to find solutions.\nTeam members should support each other's ideas, avoid bragging about personal achievements, and remain humble.\nEveryone should also get involved by contributing suggestions, helping fellow team members, and participating in team activities.\nListen Actively- acknowledge the person speaking to you by looking at the person who is speaking to you, nod, ask probing questions and if you are unclear about something that's being said ask follow up questions.","exq.ex1.0.ok":false,"exq.ex1.1":"Effective team members demonstrate behaviors such as active listening, asking and answering questions, and providing constructive feedback.\nDo not express an opinion as a fact\nThey show courtesy and respect towards others, maintain positive body language, and are patient when working with different personalities.\nTeam members should encourage collaboration, value the opinions of others, and communicate openly\nThese behaviours help create a positive environment where the team can work together effectively toward shared goals.\nRestate the original idea â To be sure you have correctly understood someone else's idea before you respond to it.","exq.ex1.1.ok":false,"exq.ex1.2":"Team dynamics refer to the relationships and interactions between members of a team and how they work together to achieve goals.\nGood team dynamics involve effective communication, cooperation, and mutual respect.\nDifferent opinions can benefit the team by bringing new ideas and perspectives.\nTeam members may experience strong feelings and emotions that need to be managed appropriately. Each member has a specific role, including leadership and support roles, and conflict may occur but can be resolved through communication and teamwork.","exq.ex1.2.ok":false,"exq.ex1.3":"I will support team members by regularly checking on their progress and helping them when challenges arise.\nI will encourage open communication and hold regular meetings where ideas, concerns, and suggestions can be shared freely.\nI will ensure that everyone understands the team's goals and objectives and has access to the resources, tools, and information needed to complete their tasks.\nWhere obstacles arise, I will assist in removing them so that team members can remain focused on achieving project objectives.","exq.ex1.3.ok":false,"exq.ex1.4":"I will ensure that all team members are consulted by involving everyone in discussions and keeping them informed about team activities and decisions. Each team member will be given an opportunity to share their ideas and opinions. I will seek input from every member, listen respectfully to their feedback, and consider their suggestions before decisions are made. Relevant information will be shared with the entire team, ensuring that nobody is excluded from the consultation process.","exq.ex1.4.ok":false,"exq.ex1.5":"Authority levels within a team are determined by the roles and responsibilities assigned to each member. The team leader or project manager typically has the highest level of authority and is responsible for managing the project, coordinating tasks, making decisions, and ensuring objectives are achieved. Other team members have defined roles and authority to perform their assigned duties. These authority levels should be agreed upon by the team so that responsibilities, reporting lines, and decision-making powers are clearly understood by everyone.","exq.ex1.5.ok":false,"exq.ex1.6":"I will ensure that authority levels are applied by clearly communicating the roles, responsibilities, and decision-making powers of each team member. Appropriate access rights, permissions, and responsibilities will be assigned according to each person's role. Team members will be expected to follow the agreed reporting structures and procedures, and their responsibilities will be monitored to ensure compliance. This helps maintain accountability and ensures that the project is managed effectively.","exq.ex1.6.ok":false,"exq.ex1.7":"I will encourage open discussions where team members can express their individual needs, concerns, and ideas. Both personal needs and team objectives will be considered when making decisions. Team agendas and goals will be clearly communicated so that everyone understands what needs to be achieved. Collaboration requires a continual balancing of different opinions, working styles, and priorities. By acknowledging everyone's needs and working together as a team, a supportive and productive environment can be created for all members.","exq.ex1.7.ok":false,"exq.ex2.0":"I will identify the needs and objectives of team members by communicating with them regularly, asking questions, and listening to their concerns and ideas. Team members should openly discuss their personal needs, hopes, and objectives so that everyone understands what is important to them. Any hidden agendas should be uncovered and discussed openly to prevent misunderstandings. I will actively seek input from all team members, including quieter members, and work with the team to identify and clarify the team's goals and objectives.","exq.ex2.0.ok":false,"exq.ex2.1":"Team coherence and spirit can be built by establishing a clear team mission and purpose so that everyone understands what the team is trying to achieve. Ground rules should be agreed upon to guide team behaviour and interactions. Responsibilities should be clearly defined so that each team member understands their role. Team leaders and members should model commitment and enthusiasm to encourage positive participation. Any conflict that arises should be depersonalised by focusing on the issue rather than the individual, helping the team remain united and focused.","exq.ex2.1.ok":false,"exq.ex2.2":"I will ensure that team members attend meetings, meet deadlines, and come prepared to contribute to team discussions and activities. Team members should publicly support the team and promote a positive image of the group both inside and outside the workplace. I will encourage energy and enthusiasm in team activities and ensure that everyone behaves professionally and respectfully. These actions help strengthen team coherence, spirit, and image.","exq.ex2.2.ok":false,"exq.ex2.3":"Trust and support are gained by being honest, reliable, respectful, and willing to help others. Team members should support each other's ideas and assist colleagues when needed. It is important not to blame others for mistakes or missed deadlines, as this damages relationships and trust. Team members should also avoid bragging about their achievements and instead focus on the success of the team. Openly discussing concerns and uncovering hidden agendas also helps build trust among colleagues.","exq.ex2.3.ok":false,"exq.ex2.4":"Feedback should be based on facts rather than personal opinions and should clearly explain the reasons behind any concerns or suggestions. When responding to an idea, it is important to restate and acknowledge the person's contribution before offering feedback. The focus should always be on critiquing the idea or behaviour and not the individual. Feedback should be given in a courteous, calm, and respectful manner. This approach helps strengthen working relationships and encourages continuous improvement.","exq.ex2.4.ok":false,"exq.ex2.5":"Differences between team members can be identified through communication, observation, and discussion. Team members may have different opinions, skills, experiences, and working styles. Each person should be given an opportunity to state their views and perspectives. Team members should seek to understand all sides of an issue and acknowledge areas of agreement and disagreement. Respecting and valuing these differences helps create a more effective and inclusive team environment.","exq.ex2.5.ok":false,"exq.ex2.6":"Showing respect is important because it builds trust, improves communication, and creates a positive team environment. Respectful listening allows team members to feel valued and understood. Courtesy in communication and behaviour helps prevent conflict and promotes cooperation. When team members treat one another with respect, they are more likely to work effectively together and contribute towards achieving team goals.","exq.ex2.6.ok":false,"exq.ex2.7":"Team members can demonstrate respect by listening carefully to others and responding courteously. Quiet team members should be encouraged to share their views and participate in discussions. Differences, talents, and unique abilities should be recognised and valued. When disagreements arise, team members should critique ideas and behaviours rather than attacking individuals personally. Treating everyone fairly and professionally creates a respectful and inclusive workplace.","exq.ex2.7.ok":false,"exq.ex2.8":"Behaviours that cause concern should be discussed promptly and openly to prevent bad feelings from developing and affecting team relationships. If concerns are left unspoken, misunderstandings and resentment can grow, which may negatively impact team performance. Discussions should focus on the specific behaviour rather than the individual as a person. Team members should be allowed to explain their side of the issue, ensuring that concerns are addressed fairly and constructively. This helps maintain healthy working relationships and supports effective teamwork.","exq.ex2.8.ok":false,"exq.ex4.2":"The stakeholders in the article need a safe and secure environment that supports tourism and community wellbeing. Tourists need protection and support services, while residents need reduced crime and a better quality of life. Cape Town Tourism and tourism businesses need a positive image and sustainable tourism growth. Government departments, police, and emergency services need effective communication and cooperation to respond to incidents. Community representatives, the media, and support programmes need accurate information and active participation to ensure the success of the Safety & Security Plan.","exq.ex4.2.ok":false,"exq.ex4.4":"Participation in Safety Forums - Stakeholders ensure open discussions by participating in Provincial, National, Local, and Cape Town Tourism Safety Forums.\n1.Membership Forum Contribution - The Membership Forum feeds information into the Cape Town and Provincial Safety and Security Forums.\n2.Co-ordination and Communication - Stakeholders work together through effective communication to create an \"alignment that really works.\"\n3.Proactive and Reactive Programmes - Ongoing programmes help prevent problems and respond effectively to incidents.\n4.Dedicated Response Mechanisms - Established reporting channels allow concerns to be raised and addressed quickly.","exq.ex4.4.ok":true,"exq.ex4.1":"1. Teamwork ensures work is done fast\n2. Fast, joined up\n3. Everyone has a role to play\n4.Team alignment","exq.ex4.1.ok":false,"exq.ex4.3":"Forums, meetings, awareness campaigns, emergency response systems and partnerships, media briefing and Practical safety and tips to visitors. Established and dedicated response mechanisms â telephone numbers such as 10111 for safety and security incidents, 10177 for Ambulance & Fire, 107 for other emergency services, and 0800 007 081 for consumer complaints.","exq.ex4.3.ok":false,"exq.ex4.5":"1. builds string working relationships between organistaions and stakeholders\n2. stakeholders are more willing to contribute resources and assistance\n3. it protects the image and integrity of the organisations goals\n4. it is beneficial for the economies jobs and wellbeing\n5. it ensures the safety of Cape Town residents ass well as its visitors/ tourists.","exq.ex4.5.ok":true,"exq.ex4.0":"1.The provincial Government of Western Cape\n2.Provincial Tourism Safety and Security Unit\n3The tourism Industry\n4.City improvement Districts\n5.SAPS\n6.The Cape Town Tourism Members\n7.Cape town tourism\n8. The provincial Government of Western Cape\n9.Provincial Tourism Safety and Security Unit1\n10. City of Cape town\n11.The tourism Indutry\n12.Business chambers\n13.City improvement Districts\n14.Community Representatives\n15.Safety and security force\n16.SAPS\n17.The Media\n18.The Cape Town Tourism Members\n19Emergency services\n20.Ctizens","exq.ex4.0.ok":false,"project.upload":"{\"name\":\"Class activity Report.docx\",\"type\":\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"size\":19078,\"uploadedAt\":\"2026-08-14T05:57:50.317Z\",\"path\":\"019c8179-b1eb-4883-8471-be7ae31f90de/logbook/mssjcmlp-Class_activity_Report.docx\"}","quiz.q-alignment.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1,0,2],\"disp\":[1,0,3,2]},\"1\":{\"kind\":\"choice\",\"picks\":[0,2,1],\"disp\":[0,3,2,1]},\"2\":{\"kind\":\"choice\",\"picks\":[1,0],\"disp\":[3,0,2,1]},\"3\":{\"kind\":\"choice\",\"picks\":[2,0,1],\"disp\":[3,2,1,0]}}","slidegate.21":true,"slidegate.22":true,"slidegate.23":true,"slidegate.24":true,"slidegate.25":true,"slidegate.26":true,"slidegate.27":true,"slidegate.28":true,"slidegate.29":true,"quiz.q-so13.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[0,3,2,1]},\"1\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[3,0,2,1]},\"2\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[3,1,2,0]},\"3\":{\"kind\":\"choice\",\"picks\":[0],\"disp\":[1,3,2,0]},\"4\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[0,2,1,3]},\"5\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[2,0,1,3]},\"6\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[0,3,1,2]},\"7\":{\"kind\":\"choice\",\"picks\":[0],\"disp\":[3,0,1,2]},\"8\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[2,3,0,1]},\"9\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[3,2,0,1]}}","detail:Learner Name":"Bonolo Mekgoe","exq.ex1.0.reviewedText":"","exq.ex1.0.marks":"","exq.ex1.0.tries":"1","exq.ex1.1.reviewedText":"","exq.ex1.1.marks":"","exq.ex1.1.tries":"1","exq.ex1.2.reviewedText":"","exq.ex1.2.marks":"","exq.ex1.2.tries":"1","exq.ex1.3.reviewedText":"","exq.ex1.3.marks":""},"exercises":{"ex1":{"best":74,"last":74,"total":78,"attempts":2},"ex2":{"best":78,"last":78,"total":82,"attempts":1},"ex4":{"best":52,"last":52,"total":66,"attempts":2}},"quizzes":{"q-alignment":{"best":4,"total":4,"attempts":3,"history":[{"score":4,"total":4,"date":"2026-10-19T20:03:12.413Z"},{"score":2,"total":4,"date":"2026-10-19T19:58:17.115Z"},{"score":1,"total":4,"date":"2026-10-19T19:55:48.553Z"}]},"q-so13":{"best":10,"total":10,"attempts":1,"history":[{"score":10,"total":10,"date":"2026-09-24T18:30:58.767Z"}]}}},"114046":{"activities":{"Lesson & Training Aids":true,"Formative Assessment":true},"logbook":{"slidegate.0":true,"slidegate.1":true,"slidegate.2":true,"slidegate.3":true,"slidegate.4":true,"slidegate.5":true,"slidegate.6":true,"exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.0":"Hardware resources â A computer network can manage shared printers, scanners, servers, storage devices and other hardware so that multiple users can access them efficiently.\nSoftware resources â Networks allow users to access shared applications, operating systems and software licences from different computers.\nNetwork services â Resources such as email, internet access, cloud services and user accounts can be managed centrally across the network.","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.0.ok":true,"exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.0.tries":"2","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.0":"Device speed impact â The speed of devices on a LAN affects response times because faster devices can process and transmit data more quickly, reducing delays.\nTransmission bandwidth effect â Higher bandwidth of the transmission line allows more data to be sent at once, improving response times by reducing congestion and wait times.\nQueuing delays â Queuing at nodes or hosts causes delays because data packets must wait their turn to be processed or transmitted, increasing response times.\nQueuing delays â Queuing at nodes or hosts causes delays because data packets must wait their turn to be processed or transmitted, increasing response times.\nProcessing time influence â Processing time at devices affects response times since longer processing delays slow down the handling of data packets on the LAN.\nMessage size and overheads â Larger message sizes and protocol overheads increase response times because more data must be transmitted and processed, causing longer delays.","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.0.ok":true,"exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.0.tries":"1","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.1":"Identify performance issues â Analysing data helps identify problems affecting network performance, enabling targeted solutions to improve response times and reliability.\nPrevent downtime â Detecting problems early through analysis prevents network downtime and service interruptions, maintaining business continuity.\nOptimize resource use â Data analysis allows optimisation of network resources by pinpointing bottlenecks and inefficient configurations.","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.1.ok":true,"exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.1.tries":"1","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.2":"Data collection for diagnosis â Diagnostic tools collect data to provide accurate information about network status and problems, facilitating effective troubleshooting.\nIdentify root causes â Tools help identify root causes of network issues by monitoring traffic, errors, and device performance.\nSupport decision making â Collected data supports informed decisions on repairs, upgrades, or configuration changes to improve network performance.","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.2.ok":true,"exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.2.tries":"1","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.3":"Faster chips improve processing â Using faster chips reduces processing time on devices, speeding up data handling and improving LAN response times.\nNetwork boards enhance connectivity â Improved network boards provide better data transmission capabilities and reduce bottlenecks, enhancing overall network performance.\nImproved protocols optimize communication â Using better network protocols increases efficiency and reduces errors, leading to faster and more reliable communication.\nFaster hard drives reduce access time â Upgrading to faster hard drives decreases data access times, improving the speed of data retrieval and storage operations.\nBetter media increases transmission quality â Using higher quality media (cables, wireless) reduces errors and signal loss, improving transmission speed and reliability.\nMore memory speeds processing â Increasing memory allows devices to handle more data simultaneously, reducing delays and improving network performance.","exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.3.ok":true,"exq.manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b.3.tries":"1","practical.pdf.final-assessor-signature":"__signature_removed__","practical.pdf.moderator-signature":"__signature_removed__","practical.pdf.assessor-signature":"__signature_removed__","practical.pdf.supervisor-signature":"__signature_removed__","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.1":"A user has limited access rights and can use applications, files and network resources needed to perform their daily work, but cannot change system settings.\nAn operator manages the day-to-day running of the network, such as backups, monitoring systems and routine tasks, but has limited authority to change major configurations.\nAn administrator has full access rights to the network and can create user accounts, assign permissions, install software and modify system settings.","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.1.ok":true,"exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.1.tries":"1","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.2":"Personal identification controls access by requiring unique usernames, passwords or biometric information so only authorised users can access network resources.\nDirectory access controls determine which users can view, create, modify or delete folders based on their assigned permissions.\nFile access control protects information by allowing only authorised users to read, edit, copy or delete specific files.\nTemporal access control restricts access according to time, allowing users to access systems only during approved working hours.\nLocation access control limits access based on where a user is connecting from, such as approved offices or network locations.","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.2.ok":true,"exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.2.tries":"1","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.3":"An access audit trail provides security and compliance by recording who accessed information and when they accessed it.\nAn access audit trail keeps a history of user activities, providing accountability and supporting investigations.\nIt helps businesses monitor user actions, improve security, detect misuse, and investigate incidents when they occur.","exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.3.ok":true,"exq.manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c.3.tries":"2","learner-guide-v2.page-8.text-12":"computers to networks. These units are actually network cards installed on computer","learner-guide-v2.page-8.text-8":"PHYSICAL COMPONENTS","learner-guide.page-1.form-name":"Bonolo","learner-guide.page-1.form-surname":"Mekgoe","learner-workbook.cover-name":"Bonolo","learner-workbook.cover-surname":"Mekgoe","learner-workbook.cover-id":"9702260283082","learner-workbook.outcome-1.1.answer":"- Network Cards(NIC)-  installed in computers to provide a connection to the network and manage data transmission\n-Cable/Wire- Provides physical connection between devices for example Coaxial cable, Twisted pair cable and Fiber-optic cable\n-Network software- manages communication and access on the LAN\n-Network Devices- devices such as printers, servers and other peripherals connected to the network   \n-Computer/Workstations- devices that are connected together to share resources and communicate","learner-workbook.outcome-1.2.answer":"Network Access Control (NAC)- is a method  that strengthen the security of a proprietary network by restricting the availability of network resources to endpoint devices that comply with a defined security policy. \n","selfassess-0":true,"selfassess-1":true,"selfassess-2":true,"selfassess-3":true,"selfassess.savedAt":"2026-10-09T09:43:50.341Z","slidegate.7":true,"exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.0":"Suppliers pros would be lower initial costs, and guarantees honored and the cons installation focused and higher maintenance","exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.0.ok":false,"exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.0.tries":"","exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.1":"","exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.1.ok":false,"exq.manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62.1.tries":"","slidegate.8":true,"learner-workbook.cover-contact":"0717538050","learner-workbook.name":"Bonolo Mekgoe","learner-workbook.organisation":"Investec","learner-workbook.unit-dept":"","learner-workbook.facilitator":"Andre Snell","learner-workbook.date-started":"2026-07-01","learner-workbook.date-completed":"2027-06-30","learner-workbook.full-names":"Bonolo Joy Megoe","learner-workbook.learner-number":"9702260283082","learner-workbook.org-2":"Investec","learner-workbook.telephone":"0717538050","learner-workbook.email":"joymekgoe@gmail.com","learner-workbook.outcome-1.3.answer":""},"exercises":{"manual-activity-5ddb79c1-37d7-4328-ae72-5dd4872fd04b":{"best":34,"last":34,"total":36,"attempts":1},"manual-activity-7fde574d-46c8-4c5e-aa8b-c6e93011e93c":{"best":24,"last":24,"total":28,"attempts":1},"manual-activity-6026ddc0-7a48-4de9-9a7e-3619ba641c62":{"best":14,"last":14,"total":16,"attempts":1}},"quizzes":{}},"114050":{"activities":{"Lesson & Training Aids":true,"Formative Assessment":true,"Summative Assessment":false,"POE Evidence":false},"logbook":{"exq.qs114050b.2":"","exq.qs114050b.2.ok":false,"exq.qs114050b.0":"","exq.qs114050b.0.ok":false,"quiz.q-business.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[3]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[0]},\"6\":{\"kind\":\"choice\",\"picks\":[0]},\"7\":{\"kind\":\"choice\",\"picks\":[0]},\"8\":{\"kind\":\"choice\",\"picks\":[0]},\"9\":{\"kind\":\"choice\",\"picks\":[0]}}","exq.qs114050b.1":"","exq.qs114050b.1.ok":false,"exq.qs114050b.3":"","exq.qs114050b.3.ok":false,"exq.qs114050b.4":"","exq.qs114050b.4.ok":false,"exq.qs114050b.5":"","exq.qs114050b.5.ok":false,"exq.qs114050b.6":"","exq.qs114050b.6.ok":false,"exq.qs114050b.7":"","exq.qs114050b.7.ok":false,"exq.qs114050b.8":"","exq.qs114050b.8.ok":false,"exq.qs114050b.9":"","exq.qs114050b.9.ok":false,"quiz.q-systems.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[0]},\"6\":{\"kind\":\"choice\",\"picks\":[0]},\"7\":{\"kind\":\"choice\",\"picks\":[0]},\"8\":{\"kind\":\"choice\",\"picks\":[0]},\"9\":{\"kind\":\"choice\",\"picks\":[0]}}","exq.qs114050sys.1":"The Input Process Output (IPO) model explains how a system works. Input refers to the data, resources, or materials that enter the system. Process is the set of activities that transforms the input into something useful. Output is the final result or information produced by the system after processing. For example, in a banking system, transaction details are the input, the system processes the transaction, and the updated account balance is the output.","exq.qs114050sys.1.ok":false,"exq.qs114050sys.4":"Transaction Processing System (TPS): Records daily transactions such as sales, payments, and orders.\nManagement Information System (MIS): Converts transaction data into useful reports for managers.\nIt serves decisions at the operational, tactical and strategic levels of the organisation.","exq.qs114050sys.4.ok":true,"exq.qs114050sys.3":"Knowledge Work System helps deal with problems requiring technical expertise or knowledge Its software includes word processing, spreadsheets, CAD, expert systems and data base systems","exq.qs114050sys.3.ok":true,"exq.qs114050sys.2":"The computer must pass the ACID test to be considered a transaction processing system. A transaction processing system collects, stores, modifies and retrieves the transactions of the organization.A transaction is an event that generates or modifies data that is eventually stored in an information system.","exq.qs114050sys.2.ok":false,"exq.qs114050sys.0":"A system is a whole made up of different parts that are connected and work together to achieve a common goal. The parts of the system are arranged in an orderly and organised manner according to a plan, with each part performing a specific function that contributes to the overall purpose of the system.","exq.qs114050sys.0.ok":false,"exq.qs114050apps.0":"Word processors are essential business tools because they allow organizations to create, edit, store, and share professional documents efficiently.\nFunctions with word processors can edit, mail merge, spell check\nEffect on the business it faster, accurate and gives a professional documents to the business\nProvide your feedback on BizChat","exq.qs114050apps.0.ok":true,"exq.qs114050apps.1":"Spread sheets are grid of cells with automatically calculate formulas\nThe spreadsheets can be used for budgets, and for predicting and what ifs analysis for the business\nThe effects of the spreadsheets can help the business be accurate and make better decisions","exq.qs114050apps.1.ok":true,"exq.qs114050apps.2":"Helps the business to have\nHelps the business have their data protected\nHelps the business holds customer, stock and sales records","exq.qs114050apps.2.ok":false,"exq.qs114050apps.2.tries":"2","exq.qs114050apps.3":"Graphics are the visual elements like logos or social media posts that businesses use to communicate information to their customers\nThe graphics like logos or adverts or slogans give the business a visual face in order to producing artwork in-house\nGraphics helps businesses to build trust and in house it is cost effective","exq.qs114050apps.3.ok":true,"exq.qs114050apps.3.tries":"1","exq.qs114050apps.4":"The office suites is a collection of software applications in one bundle\nMicrosoft 365 Word, Excel, PowerPoint, Outlook, and Access)\nThe office suites reduce costs","exq.qs114050apps.4.ok":false,"exq.qs114050apps.4.tries":"2","exq.qs114050data.1":"For data to become useful it must be processed into information that can be understood\nAn organisation converts data into information by collecting, validating, processing, analysing, and presenting raw data in a meaningful format(information). The resulting information helps managers make informed decisions, identify trends, and improve business performance.","exq.qs114050data.1.ok":true,"exq.qs114050data.0":"Businesses require data to operate and make informed decisions and achieve objectives\nData is raw, unprocessed information that is collected, captured, and stored by a business for later processing, analysis, and decision-making.","exq.qs114050data.0.ok":false,"exq.qs114050data.0.tries":"2","exq.qs114050data.1.tries":"2","exq.qs114050data.2":"The information gathered through communication helps decision-makers understand the situation clearly.\nIt reduces misunderstandings and helps everyone work towards the same goal.","exq.qs114050data.2.ok":true,"exq.qs114050data.5":"R&D and marketing share product information so products can be promoted effectively to target customers.\nCustomer surveys provide feedback about customer wants and needs, which is sent back to R&D for product improvement.","exq.qs114050data.5.ok":true,"exq.qs114050data.3":"Prices act as signals to customers, and competitor pricing helps businesses decide appropriate selling prices.\nPricing, costing and manufacturing communicate important information to ensure products are produced and sold profitably.","exq.qs114050data.3.ok":true,"slidegate.34":true,"slidegate.35":true,"slidegate.36":true,"slidegate.37":true,"slidegate.38":true,"exq.qs114050data.4":"Quality information identifies defects and errors in products so corrective action can be taken quickly.\nQuality control information monitors standards and manufacturing processes to ensure consistent product quality.","exq.qs114050data.4.ok":true,"exq.qs114050data.2.tries":"2","slidegate.0":true,"exq.qs114050data.3.tries":"2","exq.qs114050data.4.tries":"2","exq.qs114050data.5.tries":"2","exq.qs114050data.6":"Business Performance Management analyses the metrics that drive performance to improve business results and decision making.\nInformation shows what works in strong areas so successful practices can be applied to weaker areas and resources used efficiently.","exq.qs114050data.6.ok":true,"exq.qs114050data.6.tries":"2","exq.qs114050data.7":"Unauthorised access allows people to view confidential information without permission, creating security and privacy risks.\nPasswords, multi-factor authentication, access rights and encryption help prevent unauthorised access to sensitive information.","exq.qs114050data.7.ok":true,"exq.qs114050data.7.tries":"2","exq.qs114050data.8":"Unauthorised access allows hackers or insiders to read data they have no right to see, risking theft, fraud and POPIA breaches.\nDefences include passwords and multi-factor authentication, per-role access rights and encryption.","exq.qs114050data.8.ok":false,"exq.qs114050data.8.tries":"2","exq.qs114050data.9":"Disgruntled staff may deliberately misuse, steal or damage information, causing financial and reputational harm to the business.\nDisgruntled employees can leak confidential information or sabotage systems, reducing trust and business productivity.","exq.qs114050data.9.ok":false,"exq.qs114050data.9.tries":"2","exq.qs114050data.10":"The Human Resources (HR) subsystem needs information about employees and employment matters to manage the workforce effectively and employee records, contracts, leave","exq.qs114050data.10.ok":true,"exq.qs114050data.10.tries":"2","exq.qs114050data.11":"The Production subsystem needs information about materials, machinery, labour, product specifications, and production schedules to manufacture products efficiently and maintain quality standards.","exq.qs114050data.11.ok":true,"exq.qs114050data.11.tries":"1","exq.qs114050data.12":"The Marketing subsystem needs information about customers, competitors, market trends, sales, and brand performance to promote products, strengthen the brand, and increase sales and the brand assets, the results from campaigns and the feedback from customers","exq.qs114050data.12.ok":true,"exq.qs114050data.12.tries":"2","exq.qs114050data.13":"The Financial subsystem needs information about income, expenses, cash receipts, payments, and bank balances to manage cash flow, ensure financial stability, and support effective financial decision-making and invoices, payments, debtors/creditors, forecasts, budgets","exq.qs114050data.13.ok":true,"exq.qs114050data.13.tries":"2","slidegate.1":true,"slidegate.2":true},"quizzes":{"q-business":{"best":9,"total":10,"attempts":2,"history":[{"score":9,"total":10,"date":"2026-08-24T14:06:43.494Z"},{"score":6,"total":10,"date":"2026-08-24T14:03:49.823Z"}]},"q-systems":{"best":10,"total":10,"attempts":1,"history":[{"score":10,"total":10,"date":"2026-08-27T19:53:10.483Z"}]}},"exercises":{"qs114050b":{"best":20,"last":0,"total":48,"attempts":3},"qs114050sys":{"best":22,"last":22,"total":24,"attempts":1},"qs114050apps":{"best":16,"last":16,"total":30,"attempts":3},"qs114050data":{"best":34,"last":34,"total":48,"attempts":1}}},"114051":{"activities":{"Formative Assessment":true,"Lesson & Training Aids":true,"Summative Assessment":true,"POE Evidence":true},"logbook":{"quiz.q-meeting-types.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[0]}}","quiz.q-decisions-conventions.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[1]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[0]}}","exq.qs114051a.1":"The democratic meeting is about the meeting the group members share and discuss decisions \nAutocratic meeting is controlled by the leader who makes the decisions independently with limited input from others.","exq.qs114051a.1.ok":true,"exq.qs114051a.0":"ontract meetings - contract meetings are held to discuss contracts with clients and suppliers. \nTechnical review meetings evaluate designs, systems and technical work against requirements and standards.\nProject review meetings - Project review meetings are held to track project progress throughout the project.\n ","exq.qs114051a.0.ok":true,"exq.qs114051a.2":"The facilitator guides the process by managing the meeting structure, agenda, and discussion flow to keep the meeting focused and productive\nThe group participates and produces the outcome by contributing ideas, discussing issues, and working together to make decisions or solve problems.\nThe facilitator stays neutral by not taking sides or influencing decisions, allowing the group to reach its own conclusions.","exq.qs114051a.2.ok":true,"exq.qs114051a.3":"Voting-each member votes and the option with the majority is adopted to become the final decision\nConsensus- Discussion continues until every member can accept and support the final decision.\nCriteria-based rating - based rating - options are scored against agreed criteria and highest score wins\nRanking-Members place the options in order of preference from highest to lowest.\nAuthority Rule: The leader or chairperson makes the final decision after receiving input and recommendations from the group.","exq.qs114051a.3.ok":true,"exq.qs114051a.4":"A note taker should have a technical background because they understand the technical terminology used during discussions and can record information correctly. A note taker should have a technical background so that the minutes capture decisions accurately without misunderstanding important technical details.\nCan follow the technical discussion \n","exq.qs114051a.4.ok":true,"quiz.q-prep-chair.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[0]}}","quiz.q-followup.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0]},\"1\":{\"kind\":\"choice\",\"picks\":[0]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]}}","slidegate.0":true,"selfassess-6":true,"selfassess-5":true,"selfassess-4":true,"selfassess-3":true,"selfassess-2":true,"selfassess-1":true,"selfassess-0":true,"selfassess.savedAt":"2026-09-04T12:04:48.521Z","exq.qs114051a.2.tries":"1","exq.qs114051a.3.tries":"1","exq.qs114051b.0":"Venue booked and set up\nThe meeting venue must be booked in advance and set up appropriately to accommodate all participants and meeting activities.\nFacilities arranged All required facilities, including seating, lighting, ventilation, and meeting room resources, must be arranged before the meeting starts\nTechnology prepared and testedAll technology required for the meeting must be prepared and tested to ensure it functions correctly during the meeting.\nSupporting information availableAll supporting information, documents, agendas, reports, and reference materials must be available to participants before the meeting","exq.qs114051b.0.ok":true,"exq.qs114051b.0.tries":"1","exq.qs114051b.1":"Provides direction and focus â Clear outcomes keep discussions on track and prevent the meeting from going off-topic.\nThe agenda can be planned and structured around the documented outcomes\nClear, concise, documented outcomes keep the meeting focused on its purpose  participants know what must be achieved\nEnsures a common understanding â All attendees know the expected results and can work towards the same goals","exq.qs114051b.1.ok":true,"exq.qs114051b.2":"Providing advance notice ensures that attendees can clear their schedules and allocate sufficient time to prepare.\nTimeous invitations give participants enough time to prepare to study the agenda and read the documentation\nThe right people actually attend because their attendance was secured well in advance.","exq.qs114051b.2.ok":true,"exq.qs114051b.2.tries":"1","exq.qs114051b.3":"invitation - Meeting invitations must be sent out well in advance so that participants can reserve time in their schedules and prepare for the meeting.\nCompleted agenda -A completed agenda must be distributed before the meeting so that participants know the topics to be discussed and can prepare relevant input.\nSupporting documentation - All supporting documents should be provided beforehand so that attendees can read and understand the information needed for informed discussion and decision-making.","exq.qs114051b.3.ok":true,"exq.qs114051b.3.tries":"1","exq.qs114051b.1.tries":"1","exq.qs114051c.2":"Invite quiet members by name to give input and use round-robin turns so everyone speaks.\nAcknowledge each contribution and keep debate on the issue, not the person.\nSummarise areas of agreement before moving on to the next point.","exq.qs114051c.2.ok":true,"exq.qs114051c.2.tries":"2","exq.qs114051c.3":"Important or urgent topics come first before time runs out\nTime allocated for each topic\nMinor items deferred or carried over if there is no enough time","exq.qs114051c.3.ok":true,"exq.qs114051c.3.tries":"1","exq.qs114051c.0":"Rules agreed together with the members create buy-in for how the meeting is run.\nEveryone knows the procedure and expectations â how the meeting will run, how to get the floor and how decisions will be taken.\nAgreed rules prevent conflict and disputes about procedure later in the meeting.","exq.qs114051c.0.ok":true,"exq.qs114051c.0.tries":"1","exq.qs114051c.1":"The chairperson works through the agenda item by item\nThey keep the discussion focused on the current agenda item and redirects if they are off topic\nEnsures time is kept on each item","exq.qs114051c.1.ok":true,"exq.qs114051c.1.tries":"1","exq.qs114051c.4":"clearly stated and agreed to by the members.\nOwnership confirmed with members so that each member knows which task they are responsible for understand who is responsible for carrying out the decision and any deadlines involved.\nThe person responsible must be recorded and the decision confirmed with the members before the meeting moves on.","exq.qs114051c.4.ok":true,"exq.qs114051c.4.tries":"1","exq.qs114051d.0":"Minutes must record the attendees present and the apologies received.\nMinutes must capture each discussion, decision and action with its owner and timeframe.\nMinutes must follow the organisation's minute format and template as required by organisational policy.\nMinutes must be checked and distributed within the required time.","exq.qs114051d.0.ok":true,"exq.qs114051d.0.tries":"1","exq.qs114051d.1":"Decisions are communicated in the format the organisation requires, such as minutes, e-mail summaries or reports.\nDecisions must reach all affected stakeholders and participants who need them.\nDecisions must be communicated promptly within the agreed timeframe after the meeting.","exq.qs114051d.1.ok":true,"exq.qs114051d.1.tries":"1","exq.qs114051d.2":"The topics discussed and the outcomes reached for each topic.\nAny items carried over to the next meeting for further discussion or action.\nThe actions required, together with the owners responsible and the deadlines for completion.\nThe summary must be recorded in the required format prescribed by the organisation.","exq.qs114051d.2.ok":true,"exq.qs114051d.2.tries":"1"},"quizzes":{"q-meeting-types":{"best":6,"total":6,"attempts":1,"history":[{"score":6,"total":6,"date":"2026-09-04T08:51:10.643Z"}]},"q-decisions-conventions":{"best":5,"total":6,"attempts":3,"history":[{"score":5,"total":6,"date":"2026-09-04T11:48:45.581Z"},{"score":4,"total":6,"date":"2026-09-04T08:57:21.660Z"},{"score":3,"total":6,"date":"2026-09-04T08:53:43.106Z"}]},"q-prep-chair":{"best":6,"total":6,"attempts":1,"history":[{"score":6,"total":6,"date":"2026-09-04T11:53:25.808Z"}]},"q-followup":{"best":5,"total":5,"attempts":1,"history":[{"score":5,"total":5,"date":"2026-09-04T11:54:45.665Z"}]}},"exercises":{"qs114051a":{"best":24,"last":24,"total":32,"attempts":1},"qs114051b":{"best":18,"last":6,"total":26,"attempts":3},"qs114051c":{"best":20,"last":20,"total":30,"attempts":2},"qs114051d":{"best":18,"last":18,"total":22,"attempts":2}}},"114055":{"activities":{"Formative Assessment":true,"Lesson & Training Aids":true,"Summative Assessment":true,"POE Evidence":true},"logbook":{"exq.ex1.2":"The BITF (The Black Information Technology Forum) is a South African professional body that represents the black individuals who are interested in ICT. It creates opportunities for historically disadvantaged groups. By training, mentoring, and professional development programme and improve access to technology.","exq.ex1.2.ok":true,"exq.ex1.5":"Professional Competence and Continuous Learning\n\nProfessional bodies such as IITPSA encourage members to maintain and improve their skills through continuous professional development (CPD).\n\nCode of Ethics (IITPSA)\n\nThe Institute of Information Technology Professionals South Africa (IITPSA) requires members to follow a Code of Ethics that promotes professional and ethical behaviour. IT professionals should:","exq.ex1.5.ok":true,"exq.ex1.0":"Some acceptable professional practices would include \n1. keeping yourself and your ICT skill up to date as IT is an ever-evolving industry\n2. only accepting work that is within your competence\n3. providing equal training an mdopourtunities\n4. communicating clearly with team members\n5. making sure to protect privacy, security and confidential data to the best of your abilities6. properly planning, testing and restricting copyright laws, ensuring not to over test or under testing licensed software and respecting any and all copyright laws some unacceptable professional practices include \n1. misrepresenting qualifications or expertise\n2.false competence, claiming to have skills or qualifications that you do not possess\n3. software piracy, such as copying, sharing or using software without a valid license\n4.neglect, not updating your skills, not protecting data, not testing systems correctly, not fulfilling your responsibilities5. providing false information or ignoring ethical and legal requirements","exq.ex1.0.ok":true,"exq.ex1.1":"The Computer Society of South Africa is an important tool for the Information Society and guides the way ICT operates.\nit establishes and enforces ethical standards and guidelines for ICT professionals \nit grants recognized professional designations based on experience and qualifications\nThe CSSA (Computer Society of South Africa) is one of, if not the most respected associations concerned with South African Information Technology.","exq.ex1.1.ok":true,"exq.ex1.3":"The International Trade Union Confederation (ITUC) is a global trade union federation that represents workers and trade unions around the world. It is recognised as the world's largest trade union federation, representing millions of workers through its affiliated unions. In South Africa, the ITUC supports workers' rights and promotes fair labour practices through affiliated trade unions. It also helps South Africa participate in the international labour market by encouraging cooperation and trade relationships with other countries.","exq.ex1.3.ok":true,"exq.ex1.4":"the ITA aka the Information Technology Association is the trade and employer body of the ICTe industry in South Africa, the main purpose of the ITA is to represent and promote the interests of employers who operate within the IT sector.\n\nthey work to promote consistent standards of professionalism and service across the ICT industry, they also support the industry by providing a platform for networking, sharing information, influencing legislation and standards, and representing the ICT sector both nationally and internationally\n \nby encouraging professionalism and establishing industry standards, the ITA helps ensure that the South African ICT industry operates ethically, effectively, and in the best interests of its members","exq.ex1.4.ok":true,"exq.ex2.0":"The computer industry supports equality of opportunity by ensuring that people have fair access to technology, education, employment, and career advancement regardless of their race, gender, age, disability, religion, or background.\n\nSome ways the computer industry promotes equality of opportunity include:\n\nEqual Employment Opportunities\n IT companies use fair recruitment and promotion practices to ensure that all individuals are considered based on their skills, qualifications, and experience rather than personal characteristics.\n\nAccessibility for People with Disabilities\n Computer hardware and software are designed with accessibility features such as screen readers, voice recognition, captions, and magnification tools to help people with disabilities participate fully in education and employment.\n\nTraining and Skills Development\n Many organizations provide training programs, internships, learnerships, and scholarships that help people from different backgrounds gain the skills needed to work in the IT industry.\n\nRemote Work Opportunities\n Technology enables people to work from different locations, providing employment opportunities to individuals who may not be able to travel or relocate for work.\n\nAnti-Discrimination Policies\n IT companies often have policies that prohibit discrimination and harassment, creating a workplace where everyone is treated fairly and with respect.\n\nAccess to Information and Education\n Computers and the internet provide access to learning resources, online courses, and educational materials, helping people improve their knowledge and skills regardless of their location.\n\nConclusion:\n The computer industry supports equality of opportunity by promoting fair employment practices, improving accessibility, providing training opportunities, supporting remote work, preventing discrimination, and giving people access to information and education. This helps ensure that everyone has a fair chance to succeed.","exq.ex2.0.ok":true,"exq.ex2.1":"Copyright Laws and Legal Action\n Software is protected by copyright laws. Companies can take legal action against individuals or organizations that illegally copy, distribute, or use software without permission.\n\nSoftware Licensing\n Software companies use license agreements that specify how the software may be used. Users must purchase a valid license to legally install and use the software.\n\nProduct Activation and Security Measures\n Many software programs require product keys, online activation, or digital authentication to prevent unauthorized copying and use of the software.\n\nEducation and Awareness Campaigns\n The computer industry educates users about the risks of software piracy, such as legal penalties, malware infections, data loss, and financial harm to software developers.\n\nConclusion\n\nThe computer industry opposes software piracy through copyright protection, software licensing, activation technologies, and user education, helping to protect intellectual property and ensure that software developers are compensation\n","exq.ex2.1.ok":true,"selfassess-2":true,"selfassess-1":true,"selfassess-0":true,"selfassess.savedAt":"2026-08-14T12:48:44.759Z","exq.ex2.2":"Copyright Laws\n South Africa's Copyright Act 98 of 1978 protects software as intellectual property. People who copy, distribute, or sell software without permission can face legal action, fines, or penalties.\n\nSoftware Licensing\n Software companies require users and businesses to purchase valid licenses before using their software. Using unlicensed software is illegal and is considered software piracy.\n\nAnti-Piracy Organisations\n Organisations such as the Business Software Alliance (BSA) investigate reports of software piracy, promote legal software use, and help identify businesses using unlicensed software.\n\nEducation and Awareness Campaigns\n The computer industry runs awareness campaigns to educate users about the risks of software piracy, including legal consequences, security threats, malware infections, and financial losses to software developers.\n\nConclusion:\n Software piracy in South Africa is addressed through copyright laws, software licensing, anti-piracy organisations, and public awareness campaigns, which help protect software creators and encourage the legal use of software.","exq.ex2.2.ok":true,"quiz.quiz.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[1]},\"2\":{\"kind\":\"choice\",\"picks\":[2]},\"3\":{\"kind\":\"choice\",\"picks\":[1]},\"4\":{\"kind\":\"choice\",\"picks\":[3]},\"5\":{\"kind\":\"choice\",\"picks\":[1]},\"6\":{\"kind\":\"choice\",\"picks\":[1]},\"7\":{\"kind\":\"choice\",\"picks\":[1]},\"8\":{\"kind\":\"choice\",\"picks\":[1]},\"9\":{\"kind\":\"choice\",\"picks\":[1]},\"10\":{\"kind\":\"choice\",\"picks\":[1]},\"11\":{\"kind\":\"choice\",\"picks\":[1]},\"12\":{\"kind\":\"choice\",\"picks\":[2]},\"13\":{\"kind\":\"choice\",\"picks\":[1]},\"14\":{\"kind\":\"choice\",\"picks\":[0]}}"},"exercises":{"ex1":{"best":40,"last":40,"total":48,"attempts":1},"ex2":{"best":14,"last":14,"total":24,"attempts":1}},"quiz":{"best":15,"total":15,"attempts":1,"history":[{"score":15,"total":15,"date":"2026-08-21T06:36:54.326Z"}]}},"114059":{"activities":{"Lesson & Training Aids":true,"Formative Assessment":true,"Summative Assessment":true,"POE Evidence":true},"logbook":{"exq.manual-activity-61e25cd8-8548-4af8-a898-1bd559abddb6.0":"Purpose of cost/benefit analysis: Cost/benefit analysis helps decide whether a proposed change or project is worth implementing by comparing its total expected costs against its total expected benefits.\nComponents of cost/benefit analysis: The analysis includes identifying all costs (one-off and ongoing) and benefits, then calculating metrics such as the payback period.\nSubjectivity in estimating benefits: Estimating benefits can involve subjective judgements, especially when assigning monetary values to intangible factors such as reputation or risk.\nFormal and informal uses: Cost/benefit analysis can be used as a formal project appraisal tool or an informal decision-making approach for choosing the best option.\nGraphical Break-Even Analysis: A break-even point can be shown graphically by plotting costs and income or benefits against the level of output. The point where the two lines cross is the break-even point, where the total benefits or income are equal to the total costs. After this point, the project begins to provide a financial benefit.","exq.manual-activity-61e25cd8-8548-4af8-a898-1bd559abddb6.0.ok":true,"exq.manual-activity-61e25cd8-8548-4af8-a898-1bd559abddb6.0.tries":"1","exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.0":"The component is broken down into smaller, logical parts to make estimating easier and more accurate.\nA detailed task listing is created that identifies all the tasks required to complete each part of the component.\nThe estimate includes all supporting activities, such as planning, documentation, reviews, meetings, and testing, that contribute to completing the component.","exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.0.ok":true,"exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.0.tries":"1","exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.1":"The estimate includes the implementation and testing of interfaces between the component and other related components.\nDependencies on other components are considered because delays or changes in those components can affect the estimated time.\nAdditional complexity arising from integrating and testing interfaces with other components is included in the estimate.","exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.1.ok":true,"exq.manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22.1.tries":"1"},"exercises":{"manual-activity-61e25cd8-8548-4af8-a898-1bd559abddb6":{"best":10,"last":10,"total":10,"attempts":1},"manual-activity-5bf394d9-7a1c-4084-b567-7058607a1d22":{"best":12,"last":12,"total":12,"attempts":2}}},"114074":{"activities":{"Lesson & Training Aids":true}},"HWSW2":{"activities":{"Lesson & Training Aids":true,"POE Evidence":true,"Formative Assessment":true,"Summative Assessment":true},"logbook":{"quiz.hwsw2-hardware.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[1]},\"2\":{\"kind\":\"choice\",\"picks\":[2]},\"3\":{\"kind\":\"choice\",\"picks\":[1]},\"4\":{\"kind\":\"choice\",\"picks\":[3]},\"5\":{\"kind\":\"choice\",\"picks\":[2]},\"6\":{\"kind\":\"choice\",\"picks\":[2]},\"7\":{\"kind\":\"choice\",\"picks\":[2]},\"8\":{\"kind\":\"choice\",\"picks\":[2]},\"9\":{\"kind\":\"choice\",\"picks\":[1]},\"10\":{\"kind\":\"choice\",\"picks\":[1]},\"11\":{\"kind\":\"choice\",\"picks\":[2]},\"12\":{\"kind\":\"choice\",\"picks\":[1]},\"13\":{\"kind\":\"choice\",\"picks\":[1]},\"14\":{\"kind\":\"choice\",\"picks\":[2]}}","quiz.hwsw2-software.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[2]},\"2\":{\"kind\":\"choice\",\"picks\":[1]},\"3\":{\"kind\":\"choice\",\"picks\":[1]},\"4\":{\"kind\":\"choice\",\"picks\":[1]},\"5\":{\"kind\":\"choice\",\"picks\":[1]},\"6\":{\"kind\":\"choice\",\"picks\":[2]},\"7\":{\"kind\":\"choice\",\"picks\":[3]},\"8\":{\"kind\":\"choice\",\"picks\":[2]},\"9\":{\"kind\":\"choice\",\"picks\":[0]},\"10\":{\"kind\":\"choice\",\"picks\":[0]},\"11\":{\"kind\":\"choice\",\"picks\":[1]},\"12\":{\"kind\":\"choice\",\"picks\":[0]},\"13\":{\"kind\":\"choice\",\"picks\":[1]},\"14\":{\"kind\":\"choice\",\"picks\":[1]}}","quiz.hwsw2-storage.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[0],\"disp\":[2,1,0,3]},\"1\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[1,2,0,3]},\"2\":{\"kind\":\"choice\",\"picks\":[3],\"disp\":[0,1,3,2]},\"3\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[1,0,3,2]},\"4\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[0,3,2,1]},\"5\":{\"kind\":\"choice\",\"picks\":[0],\"disp\":[2,0,3,1]},\"6\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[3,2,1,0]},\"7\":{\"kind\":\"choice\",\"picks\":[3],\"disp\":[2,3,1,0]},\"8\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[0,2,1,3]},\"9\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[1,2,0,3]},\"10\":{\"kind\":\"choice\",\"picks\":[3],\"disp\":[3,1,0,2]},\"11\":{\"kind\":\"choice\",\"picks\":[0],\"disp\":[1,3,0,2]},\"12\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[2,3,0,1]},\"13\":{\"kind\":\"choice\",\"picks\":[1],\"disp\":[3,0,2,1]},\"14\":{\"kind\":\"choice\",\"picks\":[2],\"disp\":[3,1,2,0]}}","quiz.hwsw2-processing.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[3]},\"2\":{\"kind\":\"choice\",\"picks\":[1]},\"3\":{\"kind\":\"choice\",\"picks\":[0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[1]},\"6\":{\"kind\":\"choice\",\"picks\":[0]},\"7\":{\"kind\":\"choice\",\"picks\":[1]},\"8\":{\"kind\":\"choice\",\"picks\":[0]},\"9\":{\"kind\":\"choice\",\"picks\":[1]},\"10\":{\"kind\":\"choice\",\"picks\":[1]},\"11\":{\"kind\":\"choice\",\"picks\":[1]},\"12\":{\"kind\":\"choice\",\"picks\":[1]},\"13\":{\"kind\":\"choice\",\"picks\":[1]},\"14\":{\"kind\":\"choice\",\"picks\":[1]}}","slidegate.1":true},"quizzes":{"hwsw2-hardware":{"best":15,"total":15,"attempts":1,"history":[{"score":15,"total":15,"date":"2026-08-20T17:50:03.038Z"}]},"hwsw2-software":{"best":13,"total":15,"attempts":1,"history":[{"score":13,"total":15,"date":"2026-08-20T18:01:20.593Z"}]},"hwsw2-storage":{"best":14,"total":15,"attempts":4,"history":[{"score":14,"total":15,"date":"2026-10-05T20:09:12.945Z"},{"score":6,"total":15,"date":"2026-10-05T20:02:44.130Z"},{"score":10,"total":15,"date":"2026-08-20T20:24:50.867Z"}]},"hwsw2-processing":{"best":14,"total":15,"attempts":1,"history":[{"score":14,"total":15,"date":"2026-08-20T20:57:27.887Z"}]}}},"HWSW":{"activities":{"Lesson & Training Aids":true,"Formative Assessment":true,"Summative Assessment":true,"POE Evidence":true},"logbook":{"exq.hwsw-identify.0":"The best upgrade would be increasing the RAM (Random Access Memory), for example from 8 GB to 16 GB. RAM stores the data and instructions for many open applications, browser tabs, and Excel spreadsheets at the same time, allowing them to run efficiently without slowing the computer. When the RAM becomes full, Windows uses the hard drive or SSD as virtual memory (paging), and this causes the computer to run slowly because the storage drive is much slower than RAM for accessing data. The constant reading and writing of data to the disk causes the disk activity light to flicker continuously.","exq.hwsw-identify.0.ok":true,"quiz.hwsw-day1.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[1]},\"2\":{\"kind\":\"choice\",\"picks\":[1]},\"3\":{\"kind\":\"choice\",\"picks\":[1,0]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[1]},\"6\":{\"kind\":\"choice\",\"picks\":[1]},\"7\":{\"kind\":\"choice\",\"picks\":[0]},\"8\":{\"kind\":\"choice\",\"picks\":[1]},\"9\":{\"kind\":\"choice\",\"picks\":[2]},\"10\":{\"kind\":\"choice\",\"picks\":[1]},\"11\":{\"kind\":\"choice\",\"picks\":[1]}}","quiz.hwsw-day2.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[1]},\"1\":{\"kind\":\"choice\",\"picks\":[1]},\"2\":{\"kind\":\"choice\",\"picks\":[0]},\"3\":{\"kind\":\"choice\",\"picks\":[1]},\"4\":{\"kind\":\"choice\",\"picks\":[0]},\"5\":{\"kind\":\"choice\",\"picks\":[1]},\"6\":{\"kind\":\"choice\",\"picks\":[1]},\"7\":{\"kind\":\"choice\",\"picks\":[1]},\"8\":{\"kind\":\"choice\",\"picks\":[1]},\"9\":{\"kind\":\"choice\",\"picks\":[2]},\"10\":{\"kind\":\"choice\",\"picks\":[0,1,2]},\"11\":{\"kind\":\"choice\",\"picks\":[3]}}","quiz.hwsw-psu.picks":"{\"0\":{\"kind\":\"choice\",\"picks\":[2]},\"1\":{\"kind\":\"choice\",\"picks\":[1]},\"2\":{\"kind\":\"choice\",\"picks\":[1]},\"3\":{\"kind\":\"choice\",\"picks\":[1]},\"4\":{\"kind\":\"choice\",\"picks\":[2]},\"5\":{\"kind\":\"choice\",\"picks\":[1,0,2]},\"6\":{\"kind\":\"choice\",\"picks\":[2]},\"7\":{\"kind\":\"choice\",\"picks\":[1]},\"8\":{\"kind\":\"order\",\"order\":[0,1,2,3,4,5,6,7]},\"9\":{\"kind\":\"match\",\"picks\":{\"0\":0,\"1\":1,\"2\":2,\"3\":3,\"4\":4}}}","exq.hwsw-identify.1":"Both HDD(Hard Disk Drive) and the SSD (Solid State Drive) are both storage devices to store opreting system, application and user data. \nHDD uses spinning magnetic disk and a moving read/write head to access data. It consumes power, produces more heat and easily damaged from knocks or drops\nAn SSD stores data on flash memory chips and has no moving parts. This allows it to access data much faster, resulting in quicker boot times, faster application loading, improved system responsiveness, and better reliability.\nTherefore, an SSD is the preferred choice for a new laptop because it offers faster performance, better reliability, lower power consumption, and an improved user experience compared to an HDD.","exq.hwsw-identify.1.ok":true,"exq.hwsw-identify.2":"Display Port connection or HDMI If both the monitor and computer support it. DisplayPort provides enough bandwidth to carry 4K video at high refresh rates with excellent image quality. VGA should not be used because it is an analog connection that does not support modern 4K high-refresh-rate displays and can produce a less sharp image than digital connections.","exq.hwsw-identify.2.ok":true,"exq.hwsw-identify.3":"he finance department should use a laser printer because it is designed for high-volume printing and can efficiently handle around 5,000 pages per month. Laser printers use toner and laser technology to print quickly, produce clear text, and keep printing costs lower than inkjet printers. This makes them ideal for departments that regularly print large numbers of reports.","exq.hwsw-identify.3.ok":true,"exq.hwsw-identify.4":"Switch: Connects all the office PCs and other devices on the local network. It forwards data to the correct device, allowing computers to communicate and share resources.\nRouter: Connects the office network to the internet. It routes data between the local network and external networks, enabling internet access for all users.","exq.hwsw-identify.4.ok":true,"exq.hwsw-history-cloud.0":"The person regarded as the first computer programmer was Ada Lovelace. Ada Lovelace was an English mathematician who worked with Charles Babbage on early computing concepts. She wrote the first algorithm or computer program, which was a detailed set of instructions for carrying out mathematical calculations automatically. The first algorithm or computer program was created for Babbage's Analytical Engine, a mechanical computer designed to process calculations using programmed instructions. About a century before modern computers existed, her work showed that machines could follow instructions to solve complex problems.","exq.hwsw-history-cloud.0.ok":true,"exq.hwsw-history-cloud.1":"Before machines existed, the word computer referred to a person who performed complex mathematical calculations by hand. At NASA during the 1950s and 1960s, this work was carried out by human computers, including Katherine Johnson, Dorothy Vaughan, and Mary Jackson, whose calculations helped make early space missions successful","exq.hwsw-history-cloud.1.ok":true,"exq.hwsw-history-cloud.2":"ENIAC was the first programmable, general-purpose electronic digital computer developed during World War II. Its scale was remarkable because it filled a large room and used approximately 18,000 vacuum valves (vacuum tubes) to perform calculations. ENIAC was programmed by six women, who became some of the first computer programmers and were responsible for preparing the machine to solve mathematical problems. Programming = cables and switches, because programmers had to connect cables and set switches by hand instead of using stored software or programming languages.","exq.hwsw-history-cloud.2.ok":true,"exq.hwsw-history-cloud.3":"The cloud is a network of physical servers located in data centres around the world. These servers store data and run applications for users over the internet. Instead of keeping files and programs on your own computer, they are stored and processed on remote hardware that can be accessed from almost anywhere.","exq.hwsw-history-cloud.3.ok":true,"exq.hwsw-history-cloud.4":"Server Hardware\n Servers are powerful computers in a data centre that run applications, process data, host websites, and provide services to multiple users and devices across a network.\n\nEnterprise Storage Hardware\n Enterprise storage systems, such as Storage Area Networks (SANs) and storage arrays, are used to store, manage, back up, and protect large amounts of business data reliably.\n\nPower Hardware\n Power hardware includes Uninterruptible Power Supplies (UPSs), backup batteries, generators, and Power Distribution Units (PDUs). These devices ensure that equipment continues operating during power failures and electrical disruptions.\n\nCooling Hardware\n Cooling hardware includes air conditioning systems, cooling units, fans, and liquid-cooling systems. These prevent servers and other equipment from overheating and ensure reliable operation.\n\nOther Data Centre Hardware\n Other data centre hardware includes network switches, routers, firewalls, racks, cabling, and monitoring systems. These devices connect equipment, manage network traffic, improve security, and organize the data centre infrastructure.\n\nWhy your answer lost marks\n\nYou wrote:\n\n\"Rack Server-these are high performance computers mounted in tall metal frames.\"\n","exq.hwsw-history-cloud.4.ok":false},"quizzes":{"hwsw-day1":{"best":11,"total":12,"attempts":3,"history":[{"score":11,"total":12,"date":"2026-08-19T11:31:56.313Z"},{"score":9,"total":12,"date":"2026-08-19T11:28:45.813Z"},{"score":9,"total":12,"date":"2026-08-19T11:23:05.278Z"}]},"hwsw-day2":{"best":10,"total":12,"attempts":1,"history":[{"score":10,"total":12,"date":"2026-08-19T11:41:48.676Z"}]},"hwsw-psu":{"best":10,"total":10,"attempts":1,"history":[{"score":10,"total":10,"date":"2026-08-19T11:48:24.407Z"}]}},"exercises":{"hwsw-identify":{"best":28,"last":28,"total":36,"attempts":1},"hwsw-history-cloud":{"best":28,"last":28,"total":42,"attempts":3}}}}}$itss_recovery$,
